import{H as e,V as t,et as n,j as r}from"./chunks/framework.c0x6U8zS.js";import"./chunks/assets.C9d8j8hm.js";var i=JSON.parse(`{"title":"AHE01 益安枕 BLE 协议（固件 ≥ V10）","description":"","frontmatter":{},"headers":[],"relativePath":"products/ahe01/ble-protocol.md","filePath":"products/ahe01/ble-protocol.md","lastUpdated":1787045390000}`),a={name:`products/ahe01/ble-protocol.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ahe01-益安枕-ble-协议-固件-≥-v10" tabindex="-1">AHE01 益安枕 BLE 协议（固件 ≥ V10） <a class="header-anchor" href="#ahe01-益安枕-ble-协议-固件-≥-v10" aria-label="Permalink to “AHE01 益安枕 BLE 协议（固件 ≥ V10）”">​</a></h1><p>面向 <strong>APP 工程师</strong> 与 <strong>嵌入式工程师</strong> 的对照手册。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>你要找什么</th><th>看哪一节</th></tr></thead><tbody><tr><td>设备谁和谁通讯</td><td><a href="#_1-1-设备架构">§1.1 架构</a></td></tr><tr><td>CMD、cmd_type、VALUE 含义</td><td><a href="#_2-cmd-命令总表">§2 命令总表</a></td></tr><tr><td>谁写谁回、UUID、CRC、超时</td><td><a href="#_1-接入约定">§1 接入约定</a></td></tr><tr><td>标定 / 音乐 / 睡眠报告先发哪条</td><td><a href="#_3-交互时序">§3 交互时序</a></td></tr><tr><td>对照 hex 抓包</td><td><a href="#_4-抓包举例">§4 抓包举例</a></td></tr><tr><td>睡眠报告字段 / BCG 节点</td><td><a href="#_5-附录">§5 附录</a></td></tr><tr><td><code>0xFA</code> 可配置变量含义、默认值</td><td><a href="./app-vars.html">变量说明</a></td></tr></tbody></table></div><ul><li><strong>适用</strong>：主板固件 ≥ V10；广播名 <code>AHE01_</code> + 12 位十六进制 MAC（完整 MAC），例如 <code>AHE01_XXXXXXXXXXXX</code></li><li><strong>组包 / 拆包 / CRC</strong>：共用 <a href="/ahs-docs-page/common/ble-packet.html">BLE 数据包格式</a>，本文不再重复</li><li><strong>曲目 ID</strong>：<a href="./ble-music.html">本地音乐列表</a>（<strong>音乐播放器设置</strong>、<strong>闹钟设置</strong> 用）</li><li><strong>0xFA 可配置变量</strong>：<a href="./app-vars.html">变量说明（可通过 APP 配置）</a></li></ul><hr><h2 id="_1-接入约定" tabindex="-1">1. 接入约定 <a class="header-anchor" href="#_1-接入约定" aria-label="Permalink to “1. 接入约定”">​</a></h2><h3 id="_1-1-设备架构" tabindex="-1">1.1 设备架构 <a class="header-anchor" href="#_1-1-设备架构" aria-label="Permalink to “1.1 设备架构”">​</a></h3><p>AHE01（以及 AHE02 / AHE03 / AHE04）由两块板组成：</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>模块</th><th>角色</th></tr></thead><tbody><tr><td><strong>STM32 主板</strong></td><td>气囊、加热、负离子、BCG、本地音乐等业务</td></tr><tr><td><strong>ESP32 网关</strong></td><td>BLE 对 APP；对内用 UART 与主板通讯（<a href="/ahs-docs-page/common/spf-packet.html">SPF 数据包格式</a>、<a href="./spf-protocol.html">STM32 ↔ ESP32 串口协议</a>）</td></tr></tbody></table></div><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP  ←—— BLE ——→  ESP32 网关  ←—— UART（SPF）——→  STM32 主板</span></span></code></pre></div><p>APP 只看见 BLE。一条控制命令的路径是：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP 写 BLE → ESP32 转 SPF 给主板 → 主板处理并回 SPF → ESP32 从 BLE 应答 APP</span></span></code></pre></div><p>APP 等待读/写应答建议超时 <strong>5 秒</strong>。超时则视为失败，可重试。</p><h3 id="_1-2-角色与-uuid" tabindex="-1">1.2 角色与 UUID <a class="header-anchor" href="#_1-2-角色与-uuid" aria-label="Permalink to “1.2 角色与 UUID”">​</a></h3><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>角色</th><th>说明</th></tr></thead><tbody><tr><td>设备（ESP32 网关）</td><td>BLE <strong>外围设备</strong></td></tr><tr><td>APP</td><td>BLE <strong>中心设备</strong></td></tr><tr><td>字节序</td><td>多字节一律 <strong>大端</strong>（高字节在前）</td></tr></tbody></table></div><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>名称</th><th>UUID</th><th>APP</th><th>网关</th></tr></thead><tbody><tr><td>设备服务</td><td><code>0000FF00-0000-1000-8000-00805F9B34FB</code></td><td>发现服务</td><td>广播该服务</td></tr><tr><td>写入特征</td><td><code>0000FF01-0000-1000-8000-00805F9B34FB</code></td><td>只在这里下发命令</td><td>从这里收完整命令</td></tr><tr><td>通知特征</td><td><code>0000FF02-0000-1000-8000-00805F9B34FB</code></td><td>打开 Notify 收应答和上报</td><td>应答、实时数据、报告都从这里 Notify</td></tr></tbody></table></div><p>连接后 APP <strong>必须先开 Notify</strong>，再写命令，否则收不到 <code>0x11</code> / <code>0x12</code> / <code>0x13</code>。</p><p><code>cmd</code> 与 <code>cmd_type</code> 是两个字段，数字可能相同但含义不同。例如 <code>cmd_type=0x12</code> 是「设备写应答」，<strong>不是</strong>一条 CMD。</p><h3 id="_1-3-命令类型-cmd-type" tabindex="-1">1.3 命令类型（cmd_type） <a class="header-anchor" href="#_1-3-命令类型-cmd-type" aria-label="Permalink to “1.3 命令类型（cmd_type）”">​</a></h3><p>完整数据包：<code>cmd_type | cmd | length | value | crc</code>。</p><p><strong>默认单包发送</strong>：完整数据包 ≤ 18 字节时，空中帧头为 <code>01 00</code>（总包数 1、序号 0）。当前控制命令均按单包。仅睡眠报告等超长数据才拆多包，规则见 <a href="/ahs-docs-page/common/ble-packet.html">BLE 数据包格式</a>。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>cmd_type</th><th>中文</th><th>方向</th><th>成对关系</th></tr></thead><tbody><tr><td><code>0x01</code></td><td>APP 读设备数据</td><td>APP → 设备</td><td>等 <code>0x11</code>（建议 5 秒超时）</td></tr><tr><td><code>0x02</code></td><td>APP 写设备数据</td><td>APP → 设备</td><td>等 <code>0x12</code>（建议 5 秒超时）</td></tr><tr><td><code>0x11</code></td><td>设备读应答</td><td>设备 → APP</td><td>对应刚才的读</td></tr><tr><td><code>0x12</code></td><td>设备写应答</td><td>设备 → APP</td><td>对应刚才的写</td></tr><tr><td><code>0x13</code></td><td>设备主动通知</td><td>设备 → APP</td><td>单向，APP 不用先发</td></tr></tbody></table></div><p>写应答 value 若无特殊说明：<strong><code>0x01</code> 成功，<code>0x00</code> 失败</strong>。</p><p>CRC（协议要求）：<code>cmd_type ⊕ cmd ⊕ length ⊕ value[0]…</code>（不含帧头 <code>01 00</code>）。发送方必须计算并带上；接收方应按本文校验。当前网关固件为便于调试可能不校验收到的 CRC，<strong>以本文为准</strong>，正式实现不要省略。</p><h3 id="_1-4-两端各自做什么" tabindex="-1">1.4 两端各自做什么 <a class="header-anchor" href="#_1-4-两端各自做什么" aria-label="Permalink to “1.4 两端各自做什么”">​</a></h3><ul><li><strong>APP</strong>：扫 <code>AHE01_</code> + 12 位 MAC → 连 → 打开通知特征 → 按 §2 组 <code>cmd</code> / <code>value</code> 写入 → 等待对应应答（5 秒）或收通知 → 若多包则按公共格式拼接。</li><li><strong>网关 / 主板</strong>：网关拼完完整包后按 <code>cmd</code> 处理或转给主板；读/写应答从通知特征回 APP。实时数据、睡眠报告等用 <code>0x13</code> 主动上报，不要等 APP 来读。</li></ul><hr><h2 id="_2-cmd-命令总表" tabindex="-1">2. CMD 命令总表 <a class="header-anchor" href="#_2-cmd-命令总表" aria-label="Permalink to “2. CMD 命令总表”">​</a></h2><p>一张表按 <strong>cmd 从小到大</strong> 列出：<strong>cmd</strong>、<strong>cmd_type</strong>、<strong>VALUE 按字节</strong>。多字节一律大端；写应答若无另写，均为 <code>0x01</code> 成功 / <code>0x00</code> 失败。字段顺序即发送顺序。</p><p>cmd_type 列：<code>写 0x02→0x12</code> 表示 APP 写、设备写应答；<code>读 0x01→0x11</code> 表示 APP 读、设备读应答；<code>通知 0x13</code> 表示设备主动上报。</p><p>标定顺序见 <a href="#_3-2-标定枕高">§3.2</a>。睡眠报告时序见 <a href="#_3-4-睡眠报告">§3.4</a>。<code>0xFA</code> 各字段默认值、取值范围与用途见 <a href="./app-vars.html">变量说明</a>。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>cmd</th><th>中文命令</th><th>cmd_type</th><th>VALUE</th></tr></thead><tbody><tr><td><code>0x01</code></td><td>实时数据</td><td>通知 <code>0x13</code></td><td>默认 14 字节（按 length 取）<br><code>[0]</code> ahe0x：bit3–0 型号 0=AHE01 / 1=AHE02 / 2=AHE03 / 3=AHE04<br><code>[0]</code> bit4=1 出厂设置状态<br><code>[1]</code> hr：BCG 心率<br><code>[2]</code> resp：BCG 呼吸率<br><code>[3]</code> sleep_status：BCG 睡眠状态<br><code>[4]</code> status1 bit0 负离子 0 关 / 1 开<br><code>[4]</code> bit1 加热 0 关 / 1 加热<br><code>[4]</code> bit2 闹钟 0 没响 / 1 响<br><code>[4]</code> bit3 音乐 0 STOP / 1 PLAYING<br><code>[4]</code> bit4 通道 0 蓝牙音响 / 1 本地离线<br><code>[5]</code> status2 bit1–0 加热挡位 01 低 / 10 中 / 11 高<br><code>[5]</code> bit7–2 当前音乐 ID 1–32<br><code>[6-7]</code> 负离子运行时长<br><code>[8-9]</code> 加热运行时长<br><code>[10-11]</code> 音乐播放时长<br><code>[12-13]</code> 气压（可选）<br>status / value 字段可改成其它逻辑（可变逻辑）<br>产品类型看 <code>[0]</code></td></tr><tr><td><code>0x02</code></td><td>枕头基础高度</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>写/读应答：<code>airbag1…n</code> 各 1 字节<br><code>0</code> 不充气<br><code>1</code> 低<br><code>2</code> 中<br><code>3</code> 高<br>不足 6 路从 1 起填，多余 <code>0x00</code><br>写应答 1 字节 <code>0x01</code> 成功 / <code>0x00</code> 失败</td></tr><tr><td><code>0x03</code></td><td>负离子控制</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>[0]</code> 开关 0 关 / 1 开<br><code>[1-2]</code> 工作时长（分钟）<br><code>[3]</code> 浓度 0–100，默认 100</td></tr><tr><td><code>0x04</code></td><td>加热控制</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>[0]</code> 开关 0 关 / 1 开<br><code>[1-2]</code> 时长（分钟）<br><code>[3]</code> 挡位 1 低 / 2 中 / 3 高<br><code>[4]</code> 保留，固定 <code>0x00</code></td></tr><tr><td><code>0x05</code></td><td>主机系统提示音音量</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>0</code> 关提示音<br><code>1</code>–<code>100</code> 音量，默认 40</td></tr><tr><td><code>0x06</code></td><td>音乐通道选择</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>0x00</code> 蓝牙音响<br><code>0x01</code> 本地离线音乐（默认）</td></tr><tr><td><code>0x07</code><br><strong>固件版本 &gt;=12</strong></td><td>系统指示灯控制</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>写：1 字节<br><code>0</code> 关<br><code>1</code>–<code>200</code> 开 n 秒<br><code>255</code> 常亮<br><code>201</code>–<code>254</code> 非法，写应答 <code>0x00</code><br>读：无 value<br>读应答：回上次写入的那 1 字节</td></tr><tr><td><code>0x08</code></td><td>进入标定枕高模式</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>写/读：<code>0x01</code> 进入标定模式<br>写/读：<code>0x00</code> 退出标定模式（正常退出 / 非正常退出）<br>标定枕高操作都要先发本指令<br>写应答 <code>0x01</code> 成功</td></tr><tr><td><code>0x09</code></td><td>调节枕高</td><td>写 <code>0x02→0x12</code></td><td>写 1 字节动作<br>标定模式且智能匹配开启：<code>0x01</code> 充气（APP 周期发，≥3 秒）<br>标定模式且智能匹配开启：<code>0x02</code> 放气（APP 周期发，≥3 秒）<br>标定模式且智能匹配开启：<code>0x03</code> 停止（发 1 次）<br>非标定且智能匹配关闭：VALUE <code>0x11</code> 充气（不是 CMD）<br>非标定且智能匹配关闭：VALUE <code>0x12</code> 放气（不是 CMD）<br>非标定且智能匹配关闭：VALUE <code>0x13</code> 停止（不是 CMD）<br>写应答 <code>0x01</code> 成功（只对当前指令立即应答）<br>写应答 <code>0x02</code> 已到极限（主机可主动回，APP 提示松开）</td></tr><tr><td><code>0x0A</code><br><strong>固件版本 &gt;=12</strong></td><td>智能睡眠模式</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>1 字节<br><code>0</code> 关<br><code>1</code> 开</td></tr><tr><td><code>0x10</code></td><td>开始标定枕头高度 1</td><td>写 <code>0x02→0x12</code></td><td>写 <code>0x01</code><br>约等 10 秒收应答，同时提示用户「静止 n 秒」<br>写应答 <code>[0]</code> status <code>0x00</code> 失败<br>写应答 <code>[0]</code> status <code>0x01</code> 成功（此次标定完成后返回）<br>写应答 <code>[0]</code> status <code>0x02</code> 正在标定<br>写应答 <code>[1-2]</code> pressure 当前标定气压，大端</td></tr><tr><td><code>0x11</code></td><td>开始标定枕头高度 2</td><td>写 <code>0x02→0x12</code></td><td>写 <code>0x01</code><br>约等 10 秒收应答，同时提示用户「静止 n 秒」<br>写应答 <code>[0]</code> status <code>0x00</code> 失败（压差过小 / 气压不稳或其它故障）<br>失败后主机自动关闭智能匹配，APP 做相应提示<br>写应答 <code>[0]</code> status <code>0x01</code> 成功<br>写应答 <code>[0]</code> status <code>0x02</code> 正在标定<br>写应答 <code>[1-2]</code> pressure 当前标定气压，大端</td></tr><tr><td><code>0x14</code></td><td>读取气压传感器数值</td><td>读 <code>0x01→0x11</code></td><td>读：无 value<br>读应答：气压，大端</td></tr><tr><td><code>0x15</code></td><td>智能枕高匹配模式</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>0</code> 关闭<br><code>1</code> 开启</td></tr><tr><td><code>0x16</code></td><td>（预留）</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>未定义，不要当功能用</td></tr><tr><td><code>0x17</code></td><td>临时控制外设</td><td>写 <code>0x02→0x12</code></td><td><code>0x01</code> 切换当前外设运行/停止（不写存储）<br>当前在运行则停，当前停止则运行<br>外设：负离子、白噪声、加热</td></tr><tr><td><code>0x18</code></td><td>闹钟设置</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>[0]</code> 开关 0 关 / 1 开<br><code>[1]</code> 时 0–24<br><code>[2]</code> 分 0–60<br><code>[3]</code> 重复 0 一次 / 1 每天 / 2 自定义<br><code>[4]</code> 星期 bit6–0 = 六…日（自定义时有效）<br><code>[5]</code> 音乐 ID，默认 7（夏日美景）<br><code>[6]</code> 负离子唤醒 0 关 / 1–100% 浓度，默认 100<br><code>[7]</code> 加热唤醒 0 关 / 1 低 / 2 中 / 3 高<br><code>[8]</code> 香薰唤醒 0 关<br><code>[9]</code> LED 唤醒 0 关<br><code>[10]</code> 响铃模式 0 渐变（默认） / 1 固定<br><code>[11]</code> 响铃音量 1–100<br><code>[12]</code> 持续 0 一直响 / n 分钟，默认 30<br>读 value=<code>0x00</code>，读应答布局同写</td></tr><tr><td><code>0x19</code></td><td>临时关闹钟</td><td>写 <code>0x02→0x12</code></td><td><code>0x00</code>：只关当前已响的闹钟一次，不影响下次</td></tr><tr><td><code>0x20</code></td><td>日期和时间</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>写 <code>[0-1]</code> 年（大端）<br>写 <code>[2]</code> 月<br>写 <code>[3]</code> 日<br>写 <code>[4]</code> 时<br>写 <code>[5]</code> 分<br>写 <code>[6]</code> 秒<br>24 小时制，北京时间 UTC+8<br>读应答 <code>[0-6]</code> 同上 7 字节<br>读应答 <code>[7-10]</code> 时间戳 4B（能斯达模组，大端）<br>读应答 <code>[11]</code> 时区 1B（能斯达模组，char）</td></tr><tr><td><code>0x21</code></td><td>音乐音量控制</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>0</code>–<code>100</code>，默认 25</td></tr><tr><td><code>0x22</code></td><td>音乐播放器设置</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>[0]</code> 开关 0 关 / 1 开<br><code>[1]</code> 模式 0 单次 / 1 循环<br><code>[2-5]</code> 播放列表 4 字节位图，bit31–0 对应 ID32–1（1 选中 / 0 未选）<br><code>[6-7]</code> 工作时长（分钟）<br><code>[8]</code> 音量 0–100<br>实际播放按 ID1→ID32 顺序（仅播已选中的）<br>须先开播放器（<code>[0]=1</code>）再发 <code>0x23</code><br>曲目见 <a href="./ble-music.html">本地音乐列表</a></td></tr><tr><td><code>0x23</code></td><td>音乐播放控制</td><td>写 <code>0x02→0x12</code></td><td><code>0x01</code> 播放<br><code>0x02</code> 停止<br>前置：播放器设置中 en = 1</td></tr><tr><td><code>0x30</code></td><td>请求 BCG 睡眠报告</td><td>写 <code>0x02→0x12</code></td><td><code>[0-3]</code> 时间戳 UTC+8（目前未使用，可填当前）<br><code>[4]</code> 请求类型 <code>0x00</code> 开始请求<br><code>[4]</code> 请求类型 <code>0x01</code> 下一条数据<br><code>[4]</code> 请求类型 <code>0x02</code> 上一条数据<br><code>[4]</code> 请求类型 <code>0x03</code> 停止<br><code>[5]</code> 生成模式 <code>0x00</code> 普通模式<br><code>[5]</code> 生成模式 <code>0x01</code> 立即生成模式<br>生成模式仅请求类型为 <code>0x00</code> 时有效，其它请求类型仍保留 1 字节<br>写应答 1 字节表示收到并开始准备</td></tr><tr><td><code>0x31</code></td><td>睡眠报告结束上报</td><td>通知 <code>0x13</code></td><td>报告传输结束后主机主动上报<br><code>[0]</code> 状态 <code>0x01</code> 同步报告正常结束<br><code>[0]</code> 状态 <code>0x02</code> 同步报告中断<br><code>[0]</code> 状态 <code>0x03</code> 请求上一条没有数据（APP 发请求类型 <code>0x02</code> 无数据时主机发送）<br><code>[1-4]</code> 报告总字节数<br><code>[5-8]</code> 原始数据总字节数</td></tr><tr><td><code>0x32</code></td><td>睡眠报告上报</td><td>通知 <code>0x13</code></td><td>每条 30 字节（见 <a href="#_5-3-附录3-睡眠报告字段">附录 3</a>）<br>完整包超 18 字节时拆 2 包</td></tr><tr><td><code>0x33</code></td><td>睡眠报告上报原始数据</td><td>通知 <code>0x13</code></td><td>准备好后自动上报，供 APP 折线图<br>结构见 <a href="#_5-4-附录4-睡眠报告原始数据">附录 4</a></td></tr><tr><td><code>0x34</code></td><td>制作假的 BCG 睡眠数据</td><td>写 <code>0x02→0x12</code></td><td><code>0x00</code>（调试用）</td></tr><tr><td><code>0x72</code></td><td>WIFI SSID 读写</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>UTF-8 字符串<br>可能多包传输</td></tr><tr><td><code>0x73</code></td><td>WIFI 密码读写</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>UTF-8 字符串<br>可能多包传输</td></tr><tr><td><code>0x74</code></td><td>开始配网</td><td>写 <code>0x02→0x12</code></td><td>1 字节，默认 <code>0x00</code></td></tr><tr><td><code>0x75</code></td><td>读设备编号</td><td>读 <code>0x01→0x11</code></td><td>读：无 value<br>读应答：UTF-8 字符串</td></tr><tr><td><code>0xF0</code></td><td>读故障代码</td><td>读 <code>0x01→0x11</code></td><td>读：无 value<br>读应答 4 字节大端位图，<code>1</code> 为故障、解除则清 0<br>bit4 泵异常（电流过高）<br>bit3 BCG 通讯异常<br>bit2 ESP32 通讯异常<br>bit1 关机异常<br>bit0 气压传感器故障（通讯故障）<br>bit7–5 保留<br>见 <a href="#_5-2-附录2-故障代码">附录 2</a></td></tr><tr><td><code>0xF1</code></td><td>固件版本号</td><td>读 <code>0x01→0x11</code></td><td><code>[0-1]</code> 主板版本<br><code>[2-3]</code> BLE 版本<br><code>[4]</code> PLID<br>主板版本 ≤ V11 时 PLID 由网关填默认 1</td></tr><tr><td><code>0xF2</code></td><td>SIM120 蓝牙开关</td><td>写 <code>0x02→0x12</code></td><td><code>0x00</code> 关<br><code>0x01</code> 开</td></tr><tr><td><code>0xF3</code></td><td>工厂模式</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td><code>0x00</code> 关<br><code>0x01</code> 开</td></tr><tr><td><code>0xF4</code></td><td>恢复出厂设置</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>写 <code>0x00</code><br>成功后出厂标志置位（实时数据 <code>[0]</code> bit4）</td></tr><tr><td><code>0xFA</code></td><td>参数寄存器 1</td><td>写 <code>0x02→0x12</code> 读 <code>0x01→0x11</code></td><td>14 字节，详细含义见 <a href="./app-vars.html">变量说明</a><br><code>[0]</code> <code>cali_pressure_increase_percent</code><br><code>[1]</code> <code>cali_pressure_decrease_percent</code><br><code>[2-3]</code> <code>max_pressure_protect_value</code><br><code>[4]</code> <code>pressure_sample_period</code><br><code>[5]</code> <code>pressure_stable_percent</code><br><code>[6]</code> <code>pressure_stable_duration</code><br><code>[7]</code> <code>total_adjust_count_per_sleep</code><br><code>[8]</code> <code>base_pillow_height</code><br><code>[9]</code> <code>motion_detect_interval</code><br><code>[10]</code> <code>motion_cont_threshold</code><br><code>[11]</code> <code>change_height_motion_cnt</code><br><code>[12]</code> <code>motion_interv_window</code><br><code>[13]</code> 保留</td></tr><tr><td><code>0xFB</code></td><td>参数寄存器 2</td><td>读 <code>0x01→0x11</code></td><td>14 字节只读<br><code>[0-1]</code> 实时原始气压<br><code>[2-3]</code> 实时滤波气压<br><code>[4-5]</code> 仰卧/侧卧气压变化量<br><code>[6]</code> 当前卧姿 0 未初始化 / 1 仰卧 / 2 侧卧<br>其余保留<br>可 ≥1 秒周期读</td></tr><tr><td><code>0xFC</code></td><td>参数寄存器 3</td><td>读 <code>0x01→0x11</code></td><td><code>[0]</code> 智能匹配开关<br>标定点 1 气压 2 字节（仅 <code>[0]</code> 为 1/2/3）<br>标定点 2 气压 2 字节（仅 <code>[0]</code> 为 1/2/3）<br>标定点 3 气压 2 字节（仅 <code>[0]</code> 为 1/2/3）<br>手动模式基础枕高气压 2 字节（仅 <code>[0]</code> 为 0）</td></tr></tbody></table></div><p>命令随固件可能增补，以本文为准。</p><hr><h2 id="_3-交互时序" tabindex="-1">3. 交互时序 <a class="header-anchor" href="#_3-交互时序" aria-label="Permalink to “3. 交互时序”">​</a></h2><p>按场景组包。VALUE 以 §2 为准。控制类写/读应答默认走「APP → BLE → SPF → 主板 → BLE → APP」，等待 <strong>5 秒</strong>。</p><h3 id="_3-1-连接后建议顺序" tabindex="-1">3.1 连接后建议顺序 <a class="header-anchor" href="#_3-1-连接后建议顺序" aria-label="Permalink to “3.1 连接后建议顺序”">​</a></h3><ol><li>扫 <code>AHE01_</code> + 12 位 MAC，连接，打开通知特征。</li><li><strong>固件版本号</strong> <code>0xF1</code>：确认主板版本 ≥ V10，记下 PLID。</li><li><strong>读设备编号</strong> <code>0x75</code>。</li><li>等 <strong>实时数据</strong> <code>0x01</code> 通知，从 <code>[0]</code> 确认型号为 AHE01。</li><li><strong>日期和时间</strong> <code>0x20</code> 写入北京时间（24 小时制）。</li><li>持续收 <strong>实时数据</strong>，不要轮询读它。</li></ol><h3 id="_3-2-标定枕高" tabindex="-1">3.2 标定枕高 <a class="header-anchor" href="#_3-2-标定枕高" aria-label="Permalink to “3.2 标定枕高”">​</a></h3><p>前置：先写 <strong>智能枕高匹配模式</strong> 为开启（<code>1</code>）。所有标定操作都要先发 <strong>进入标定枕高模式</strong>。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP                         设备（网关+主板）</span></span>
<span class="line"><span> |-- 进入标定枕高模式 0x01 --&gt; |     （等写应答，5 秒）</span></span>
<span class="line"><span> |&lt;--------- 写应答 成功 -----|</span></span>
<span class="line"><span> |-- 开始标定枕头高度 1 -----&gt; |     （约 10 秒，提示「静止 n 秒」）</span></span>
<span class="line"><span> |&lt;---- status + 气压 --------|</span></span>
<span class="line"><span> |-- 开始标定枕头高度 2 -----&gt; |     （失败则主机自动关智能匹配）</span></span>
<span class="line"><span> |&lt;---- status + 气压 --------|</span></span>
<span class="line"><span> |-- 调节枕高 充气/放气/停止-&gt; |     （充/放气 ≥3 秒周期）</span></span>
<span class="line"><span> |&lt;---- 成功 或 已到极限 -----|</span></span>
<span class="line"><span> |-- 进入标定枕高模式 0x00 --&gt; |     退出（正常 / 非正常）</span></span>
<span class="line"><span> |&lt;--------- 写应答 ----------|</span></span></code></pre></div><p>非标定且智能匹配关闭时，调节枕高 VALUE 改用 <code>0x11</code> / <code>0x12</code> / <code>0x13</code>。</p><h3 id="_3-3-本地音乐" tabindex="-1">3.3 本地音乐 <a class="header-anchor" href="#_3-3-本地音乐" aria-label="Permalink to “3.3 本地音乐”">​</a></h3><ol><li><strong>音乐通道选择</strong> <code>0x06</code> = 本地离线音乐。</li><li><strong>音乐播放器设置</strong>：开、选 ID 位图、时长、音量。播放按 ID1→ID32 顺序。</li><li><strong>音乐播放控制</strong>：播放 / 停止（须 en = 1）。</li><li>状态看 <strong>实时数据</strong>（是否在播、当前 ID、时长）。音量也可单独用 <strong>音乐音量控制</strong>。</li></ol><h3 id="_3-4-睡眠报告" tabindex="-1">3.4 睡眠报告 <a class="header-anchor" href="#_3-4-睡眠报告" aria-label="Permalink to “3.4 睡眠报告”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP 写 请求 BCG 睡眠报告（开始）     → 等写应答（5 秒）</span></span>
<span class="line"><span>设备 写应答（开始准备）</span></span>
<span class="line"><span>设备 通知 睡眠报告上报 / 原始数据   ← 可多包、可多条</span></span>
<span class="line"><span>设备 通知 睡眠报告结束上报</span></span>
<span class="line"><span>APP 若还要：请求类型 = 下一条 / 上一条 / 停止</span></span></code></pre></div><p>每条 30 字节报告常拆 2 包。APP 必须拼完再算 CRC。30 字节字段见 <a href="#_5-3-附录3-睡眠报告字段">附录 3</a>，原始数据见 <a href="#_5-4-附录4-睡眠报告原始数据">附录 4</a>。</p><h3 id="_3-5-恢复出厂" tabindex="-1">3.5 恢复出厂 <a class="header-anchor" href="#_3-5-恢复出厂" aria-label="Permalink to “3.5 恢复出厂”">​</a></h3><p><strong>恢复出厂设置</strong>：成功后出厂标志置位，可在实时数据 <code>[0]</code> bit4 看到。</p><p>配网相关命令为 <a href="#_2-cmd-命令总表">§2</a> 中 <code>0x72</code> / <code>0x73</code> / <code>0x74</code>，不要走产品交互流程。</p><h3 id="_3-6-控制外设-负离子-加热等" tabindex="-1">3.6 控制外设（负离子 / 加热等） <a class="header-anchor" href="#_3-6-控制外设-负离子-加热等" aria-label="Permalink to “3.6 控制外设（负离子 / 加热等）”">​</a></h3><p>写对应控制命令 → 等写应答（5 秒）→ 之后以 <strong>实时数据</strong> 状态位为准。只想暂停、不改已存储配置：用 <strong>临时控制外设</strong>。</p><hr><h2 id="_4-抓包举例" tabindex="-1">4. 抓包举例 <a class="header-anchor" href="#_4-抓包举例" aria-label="Permalink to “4. 抓包举例”">​</a></h2><p>下列控制命令均为<strong>单包</strong>（帧头 <code>01 00</code>）。<code>crc</code> 按 §1.3 计算。命令名称与 VALUE 以 §2 为准（举例仅作对照，不以过期抓包为准）。</p><h3 id="_4-1-写枕头基础高度-六气囊均为-2-档" tabindex="-1">4.1 写枕头基础高度（六气囊均为 2 档） <a class="header-anchor" href="#_4-1-写枕头基础高度-六气囊均为-2-档" aria-label="Permalink to “4.1 写枕头基础高度（六气囊均为 2 档）”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP：  01 00  02  02  06  02 02 02 02 02 02  crc</span></span>
<span class="line"><span>              │   │   │   └─ 六个气囊挡位</span></span>
<span class="line"><span>              │   │   └─ length=6</span></span>
<span class="line"><span>              │   └─ 枕头基础高度</span></span>
<span class="line"><span>              └─ APP 写设备数据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>设备： 01 00  12  02  01  01  crc     写应答 cmd_type=0x12，value 0x01 成功</span></span></code></pre></div><h3 id="_4-2-读枕头基础高度" tabindex="-1">4.2 读枕头基础高度 <a class="header-anchor" href="#_4-2-读枕头基础高度" aria-label="Permalink to “4.2 读枕头基础高度”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP：  01 00  01  02  00  crc</span></span>
<span class="line"><span>设备： 01 00  11  02  06  02 02 02 02 02 02  crc</span></span></code></pre></div><h3 id="_4-3-写-读日期和时间" tabindex="-1">4.3 写 / 读日期和时间 <a class="header-anchor" href="#_4-3-写-读日期和时间" aria-label="Permalink to “4.3 写 / 读日期和时间”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP 写：01 00  02  20  07  年高 年低 月 日 时 分 秒  crc</span></span>
<span class="line"><span>设备：  01 00  12  20  01  01  crc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>APP 读：01 00  01  20  01  00  crc</span></span>
<span class="line"><span>设备：  01 00  11  20  0C  年高 年低 月 日 时 分 秒  ts3 ts2 ts1 ts0 时区  crc</span></span></code></pre></div><p>读应答 length=<code>0x0C</code>（7 字节时钟 + 4 字节时间戳 + 1 字节时区），与 §2 命令表一致。</p><h3 id="_4-4-设备上报实时数据-单包" tabindex="-1">4.4 设备上报实时数据（单包） <a class="header-anchor" href="#_4-4-设备上报实时数据-单包" aria-label="Permalink to “4.4 设备上报实时数据（单包）”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备： 01 00  13  01  0E  （14 字节，见 §2 \`0x01\`）  crc</span></span>
<span class="line"><span>              │   └─ 实时数据</span></span>
<span class="line"><span>              └─ 设备主动通知</span></span></code></pre></div><p>偏移 0 的低 4 位即为产品型号（AHE01 = 0）。</p><h3 id="_4-5-请求睡眠报告" tabindex="-1">4.5 请求睡眠报告 <a class="header-anchor" href="#_4-5-请求睡眠报告" aria-label="Permalink to “4.5 请求睡眠报告”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP：  01 00  02  30  06  时间戳4B  请求类型  生成模式  crc</span></span>
<span class="line"><span>设备： 01 00  12  30  01  01  crc</span></span></code></pre></div><p>value 共 6 字节（时间戳 4B + 请求类型 1B + 生成模式 1B）。</p><h3 id="_4-6-睡眠报告-30-字节拆-2-包-通知-例外" tabindex="-1">4.6 睡眠报告 30 字节拆 2 包（通知，例外） <a class="header-anchor" href="#_4-6-睡眠报告-30-字节拆-2-包-通知-例外" aria-label="Permalink to “4.6 睡眠报告 30 字节拆 2 包（通知，例外）”">​</a></h3><p>控制命令默认单包；本条因完整包超过 18 字节才分包。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>包1： 02 00  13  32  1E  第 1–15 字节</span></span>
<span class="line"><span>包2： 02 01  第 16–30 字节  crc</span></span></code></pre></div><p>APP 按序号拼回完整数据包，校验 CRC 后再取 30 字节报告（字段见 <a href="#_5-3-附录3-睡眠报告字段">附录 3</a>）。</p><hr><h2 id="_5-附录" tabindex="-1">5. 附录 <a class="header-anchor" href="#_5-附录" aria-label="Permalink to “5. 附录”">​</a></h2><p>原协议 PDF 附件。空中传输仍按本文：<strong>多字节大端</strong>。</p><h3 id="_5-1-附录1-bcg模组发送数据格式" tabindex="-1">5.1 附录1 BCG模组发送数据格式 <a class="header-anchor" href="#_5-1-附录1-bcg模组发送数据格式" aria-label="Permalink to “5.1 附录1 BCG模组发送数据格式”">​</a></h3><p><img src="/ahs-docs-page/assets/pdf-p09-img1.CT2sQfoZ.png" alt="BCG 实时数据节点" width="849" height="495"></p><h3 id="_5-2-附录2-故障代码" tabindex="-1">5.2 附录2 故障代码 <a class="header-anchor" href="#_5-2-附录2-故障代码" aria-label="Permalink to “5.2 附录2 故障代码”">​</a></h3><p>4 字节，高字节在前。对应位为 <code>1</code> 表示故障，解除后清 <code>0</code>。读命令见 <code>0xF0</code>。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>故障代码</th><th>描述</th><th>原因</th></tr></thead><tbody><tr><td>bit7</td><td>保留</td><td></td></tr><tr><td>bit6</td><td>保留</td><td></td></tr><tr><td>bit5</td><td>保留</td><td></td></tr><tr><td>bit4</td><td>泵异常</td><td>电流过高</td></tr><tr><td>bit3</td><td>BCG 通讯异常</td><td></td></tr><tr><td>bit2</td><td>ESP32 通讯异常</td><td></td></tr><tr><td>bit1</td><td>关机异常</td><td></td></tr><tr><td>bit0</td><td>气压传感器故障</td><td>通讯故障</td></tr></tbody></table></div><h3 id="_5-3-附录3-睡眠报告字段" tabindex="-1">5.3 附录3 睡眠报告字段 <a class="header-anchor" href="#_5-3-附录3-睡眠报告字段" aria-label="Permalink to “5.3 附录3 睡眠报告字段”">​</a></h3><p><code>0x32</code> 每条 30 字节 = 评分明细 10 字节 + 报告统计 20 字节。</p><p><img src="/ahs-docs-page/assets/pdf-p10-img1.DKGJBThC.png" alt="睡眠报告结构" width="1146" height="698"></p><p><img src="/ahs-docs-page/assets/pdf-p10-img2.D_WXrTTT.png" alt="字段说明" width="926" height="611"></p><p><img src="/ahs-docs-page/assets/pdf-p10-img3.DNuHPJRU.png" alt="夜间/白日报告区分" width="916" height="286"></p><p>在床时间图示：</p><p><img src="/ahs-docs-page/assets/pdf-p11-img1.Dm1v5D67.png" alt="在床时间图示" width="641" height="329"></p><h3 id="_5-4-附录4-睡眠报告原始数据" tabindex="-1">5.4 附录4 睡眠报告原始数据 <a class="header-anchor" href="#_5-4-附录4-睡眠报告原始数据" aria-label="Permalink to “5.4 附录4 睡眠报告原始数据”">​</a></h3><p>去掉数据包头和尾后：<code>时间戳(4 字节) + NODE1 + … + NODEn</code>。每个 NODE 5 字节，对应 1 分钟。<code>0x33</code> 用于 APP 折线图。</p><p><img src="/ahs-docs-page/assets/pdf-p11-img2.D4sRPaot.png" alt="NODE 5 字节布局" width="966" height="367"></p>`,90)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};